#!/usr/bin/env node
/** Regenerate sdk/src/deployments.ts from deployments/*.json (use after a Remix deployment). */
const fs = require("fs");
const path = require("path");
const root = path.resolve(__dirname, "../..");
const dir = path.join(root, "deployments");
const all = {};
for (const f of fs.readdirSync(dir).filter((f) => /^\d+\.json$/.test(f))) {
  const d = JSON.parse(fs.readFileSync(path.join(dir, f), "utf8"));
  all[d.chainId] = d;
}
fs.writeFileSync(
  path.join(root, "sdk", "src", "deployments.ts"),
  '// AUTO-GENERATED by contracts/scripts/deploy.ts — do not edit.\nimport type { Deployment } from "./types";\n\n' +
    `export const DEPLOYMENTS: Record<number, Deployment> = ${JSON.stringify(all, null, 2)};\n`,
);
console.log(`synced ${Object.keys(all).length} deployment(s): ${Object.keys(all).join(", ")}`);
